Lemma stack0_ok_sh' : forall A k, 0 <= A -> 0 <= k -> A + 8 * k <= aceil -> stack0_ok (sh A, sh A + k).
Proof.
  intros A k HA Hk Hhi. pose proof (stack0_ok_sh A (8 * k) HA ltac:(lia) Hhi) as K.
  unfold nsh in K. replace ((8 * k + 7) / 8) with k in K by (Z.div_mod_to_equations; nia). exact K.
Qed.

