Lemma stack0_ok_shr : forall A k, 0 <= A -> 0 <= k -> A + 8 * k <= aceil ->
  stack0_ok (Z.shiftr A 3 + 2147450880, Z.shiftr A 3 + 2147450880 + k).
Proof. intros A k HA Hk Hhi. rewrite <- ASHADOW_BASE_val. rewrite (sh_shiftr A HA). apply stack0_ok_sh'; lia. Qed.

